1	// The home screen and the app's signature interaction: a blank page you can
2	// type on immediately. Swiping up files the page away (the note slides off the
3	// top) and a fresh blank page is ready underneath — same gesture as the
4	// original app. Notes land in Feed via the desktop-compatible core.
5	
6	import { Ionicons } from "@expo/vector-icons";
7	import { DrawerActions, useNavigation } from "@react-navigation/native";
8	import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
9	import { useEffect, useMemo, useRef, useState } from "react";
10	import {
11	  Keyboard,
12	  Pressable,
13	  StyleSheet,
14	  TextInput,
15	  useWindowDimensions,
16	  View,
17	} from "react-native";
18	import { Gesture, GestureDetector } from "react-native-gesture-handler";
19	import Animated, {
20	  runOnJS,
21	  useAnimatedStyle,
22	  useSharedValue,
23	  withSpring,
24	  withTiming,
25	} from "react-native-reanimated";
26	import { useSafeAreaInsets } from "react-native-safe-area-context";
27	
28	import * as core from "@typenotes/mobile-core/core-api";
29	
30	import { CaptureSession } from "../lib/capture";
31	import type { RootStackParamList } from "../navigation";
32	import { useNotesStore } from "../state/notes-store";
33	import { useTheme } from "../theme";
34	
35	const SWIPE_DISTANCE = 90;
36	const SWIPE_VELOCITY = -900;
37	
38	export const CaptureScreen = () => {
39	  const theme = useTheme();
40	  const insets = useSafeAreaInsets();
41	  const navigation =
42	    useNavigation<NativeStackNavigationProp<RootStackParamList>>();
43	  const { height } = useWindowDimensions();
44	
45	  const [text, setText] = useState("");
46	  const [pageKey, setPageKey] = useState(0);
47	  const [iconsVisible, setIconsVisible] = useState(true);
48	  const iconsOpacity = useSharedValue(1);
49	  const inputRef = useRef<TextInput>(null);
50	
51	  const session = useMemo(
52	    () =>
53	      new CaptureSession({
54	        createNote: async (content) => (await core.createNote({ content })).path,
55	        writeNote: core.writeNote,
56	        deleteNote: (path) => core.deleteItems([path]),
57	      }),
58	    []
59	  );
60	
61	  // Flush the draft when the screen loses focus (navigation away).
62	  useEffect(
63	    () => navigation.addListener("blur", () => void session.flush()),
64	    [navigation, session]
65	  );
66	
67	  const translateY = useSharedValue(0);
68	
69	  // Wrap Keyboard.dismiss so the worklet captures this plain closure rather
70	  // than the bare method — passing Keyboard.dismiss straight to runOnJS makes
71	  // worklets try to copy its owner (KeyboardImpl), which it can't serialize.
