1	// Voice capture. Records with expo-audio, saves through the core (which
2	// creates a Feed note with transcription_status: pending), then queues
3	// transcription according to the working folder's transcription_mode:
4	//
5	//   assemblyai → cloud queue now, on this device
6	//   native     → on-device speech recognition via the expo-speech-recognition
7	//                provider (lib/native-transcription), run by the core's queue
8	//   desktop    → stays pending; a synced desktop picks it up (local Whisper)
9	//   off        → stays pending until triggered manually
10	
11	import { useNavigation } from "@react-navigation/native";
12	import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
13	import {
14	  AudioModule,
15	  RecordingPresets,
16	  setAudioModeAsync,
17	  useAudioRecorder,
18	  useAudioRecorderState,
19	} from "expo-audio";
20	import * as FileSystem from "expo-file-system/legacy";
21	import { useEffect, useState } from "react";
22	import { ScrollView, StyleSheet, Text, View } from "react-native";
23	
24	import * as core from "@typenotes/mobile-core/core-api";
25	import { getErrorMessage } from "@typenotes/shared/errors";
26	import {
27	  effectiveTranscriptionMode,
28	  type TranscriptionMode,
29	} from "@typenotes/shared/types";
30	
31	import { nativeTranscriptionProvider } from "../lib/native-transcription";
32	import type { RootStackParamList } from "../navigation";
33	import { useNotesStore } from "../state/notes-store";
34	import { activeProfile, useSettingsStore } from "../state/settings-store";
35	import { useTheme } from "../theme";
36	import { Button, InlineNote } from "../ui/controls";
37	
38	const MODE_EXPLANATION: Record<TranscriptionMode, string> = {
39	  assemblyai: "Will transcribe now via AssemblyAI.",
40	  native: "Will transcribe on this device with the system speech recognizer.",
41	  desktop: "Will stay pending until your desktop syncs and transcribes it.",
42	  off: "Automatic transcription is off — the recording stays pending.",
43	};
44	
45	type SaveOutcome = {
46	  notePath: string;
47	  detail: string;
48	};
49	
50	export const RecordScreen = () => {
51	  const theme = useTheme();
52	  const navigation =
53	    useNavigation<NativeStackNavigationProp<RootStackParamList>>();
54	  const recorder = useAudioRecorder(RecordingPresets.HIGH_QUALITY);
55	  const recorderState = useAudioRecorderState(recorder);
56	
57	  const [permitted, setPermitted] = useState<boolean | null>(null);
58	  const [busy, setBusy] = useState(false);
59	  const [outcome, setOutcome] = useState<SaveOutcome | null>(null);
60	  const [error, setError] = useState<string | null>(null);
61	
62	  const snapshot = useSettingsStore((s) => s.snapshot);
63	  const settings = activeProfile(snapshot)?.settings;
64	  const mode: TranscriptionMode = settings
65	    ? effectiveTranscriptionMode(settings)
66	    : "desktop";
67	
68	  useEffect(() => {
69	    void (async () => {
70	      const permission = await AudioModule.requestRecordingPermissionsAsync();
71	      setPermitted(permission.granted);
72	      if (permission.granted) {
73	        await setAudioModeAsync({ allowsRecording: true, playsInSilentMode: true });
74	      }
75	    })();
76	  }, []);
77	
78	  const start = async () => {
79	    setError(null);
80	    setOutcome(null);
81	    try {
82	      await recorder.prepareToRecordAsync();
83	      recorder.record();
84	    } catch (err) {
85	      setError(getErrorMessage(err));
86	    }
87	  };
88	
89	  const stopAndSave = async () => {
90	    setBusy(true);
91	    try {
92	      await recorder.stop();
93	      const uri = recorder.uri;
94	      if (!uri) {
95	        throw new Error("Recorder produced no file.");
96	      }
97	      const audioBase64 = await FileSystem.readAsStringAsync(uri, {
98	        encoding: "base64",
99	      });
100	      const saved = await core.saveAudioRecording({
101	        audio_base64: audioBase64,
102	        mime_type: "audio/mp4",
103	      });
104	
105	      let detail = MODE_EXPLANATION[mode];
106	      if (mode === "assemblyai") {
107	        try {
108	          const queued = await core.queueRecordingTranscriptions();
109	          detail = `Queued for AssemblyAI (${queued.queued} queued, ${queued.in_flight} in flight).`;
110	        } catch (queueError) {
111	          detail = `Saved, but queueing failed: ${getErrorMessage(queueError)}`;
112	        }
113	      } else if (mode === "native") {
114	        try {
115	          const queued = await core.queueProviderTranscriptions(
116	            nativeTranscriptionProvider
117	          );
118	          detail = `Transcribing on this device (${queued.queued} queued, ${queued.in_flight} in flight).`;
119	        } catch (queueError) {
120	          detail = `Saved, but queueing failed: ${getErrorMessage(queueError)}`;
121	        }
122	      }
123	      setOutcome({ notePath: saved.note_path, detail });
124	      void useNotesStore.getState().refresh();
125	    } catch (err) {
126	      setError(getErrorMessage(err));
127	    } finally {
128	      setBusy(false);
129	    }
130	  };
131	
132	  const recording = recorderState.isRecording;
133	  const seconds = Math.floor((recorderState.durationMillis ?? 0) / 1000);
134	
135	  return (
136	    <ScrollView
137	      style={{ backgroundColor: theme.colors.background }}
138	      contentContainerStyle={styles.content}
139	    >
140	      {permitted === false ? (
141	        <Text style={{ color: theme.colors.danger }}>
142	          Microphone permission was denied. Enable it in system settings.
143	        </Text>
144	      ) : (
145	        <>
146	          <View style={styles.meter}>
147	            <Text style={[styles.timer, { color: theme.colors.text }]}>
148	              {recording
149	                ? `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`
150	                : "Ready"}
151	            </Text>
152	            <InlineNote>{MODE_EXPLANATION[mode]}</InlineNote>
153	          </View>
154	
155	          {recording ? (
156	            <Button title="Stop & save" kind="danger" onPress={() => void stopAndSave()} disabled={busy} />
157	          ) : (
158	            <Button title="Start recording" onPress={() => void start()} disabled={busy || permitted === null} />
159	          )}
160	
161	          {outcome ? (
162	            <View style={styles.outcome}>
163	              <Text style={{ color: theme.colors.success, fontWeight: "600" }}>
164	                Recording saved.
165	              </Text>
166	              <InlineNote>{outcome.detail}</InlineNote>
167	              <Button
168	                title="Open note"
169	                kind="secondary"
170	                onPress={() =>
171	                  navigation.replace("Editor", {
172	                    path: outcome.notePath,
173	                    title: "Voice recording",
174	                  })
175	                }
176	              />
177	            </View>
178	          ) : null}
179	          {error ? <Text style={{ color: theme.colors.danger }}>{error}</Text> : null}
180	        </>
181	      )}
182	    </ScrollView>
183	  );
184	};
185	
186	const styles = StyleSheet.create({
187	  content: { padding: 20, gap: 16 },
188	  meter: { alignItems: "center", gap: 8, paddingVertical: 24 },
189	  timer: { fontSize: 44, fontVariant: ["tabular-nums"], fontWeight: "300" },
190	  outcome: { gap: 10, paddingTop: 8 },
191	});
